use super::*;
use crate::recurring::Cadence;

/// The nth occurrence after an anchor, by the cadence's own unit.
pub(crate) fn step(anchor: &str, cadence: Cadence, n: i64) -> Option<String> {
    match cadence {
        Cadence::Weekly => Some(add_days(anchor, 7 * n)),
        Cadence::Biweekly => Some(add_days(anchor, 14 * n)),
        Cadence::Monthly => Some(add_calendar_months(anchor, n)),
        Cadence::Quarterly => Some(add_calendar_months(anchor, 3 * n)),
        Cadence::Annual => Some(add_calendar_months(anchor, 12 * n)),
        // An irregular charge has no next date to predict. Inventing one would put a number on the
        // calendar that nothing observed, which is worse than the charge being absent from it.
        Cadence::Irregular => None,
    }
}
